import os
import re
from pathlib import Path

ROOT = Path(r"H:/01_AI_SKILLS_AGENTS/_extracted")

def extract_skill_name(content):
    """Extract the skill name from frontmatter."""
    match = re.search(r'^---\s*name:\s*(.+?)\s*---', content, re.MULTILINE | re.DOTALL)
    if match:
        return match.group(1).strip().lower()
    return None

def get_pragmatic_name(name, content):
    """Generate a pragmatic, descriptive name for the skill."""
    # Clean up the name
    name = re.sub(r'[_\s]+', '-', name)
    name = re.sub(r'[^a-z0-9\-]', '', name)
    name = name[:50]  # Limit length

    # Skill-specific renaming logic
    if 'deep-brainstorm' in name or 'brainstorm' in name:
        return 'ideation-brainstorm'
    elif 'psychology-agent' in name or 'psychology' in name:
        return 'psychological-support'
    elif 'writer-agent' in name or 'writer' in name:
        return 'plain-writing'
    elif 'davinci-resolve' in name:
        return f'davinci-{name.replace("davinci-resolve-", "")}'
