# Process each SKILL.md
print("Processing SKILL.md files...")
renames = []

for skill_path in sorted(ROOT.rglob("SKILL.md")):
    try:
        content = skill_path.read_text(encoding='utf-8')
        old_name = extract_skill_name(content)

        if old_name:
            new_name = get_pragmatic_name(old_name, content)
            new_path = skill_path.parent / f"{new_name}.md"

            # Avoid overwriting
            if new_path.exists():
                new_name = f"{new_name}_2"
                new_path = skill_path.parent / f"{new_name}.md"

            renames.append({
                'old': skill_path,
                'new': new_path,
                'old_name': old_name,
                'new_name': new_name
            })

    except Exception as e:
        print(f"Error processing {skill_path}: {e}")

# Apply renames
print(f"\nApplying {len(renames)} renames...")
for rename in renames:
    try:
        if not rename['new'].exists():
            rename['old'].rename(rename['new'])
            print(f"  {rename['old_name']} -> {rename['new_name']}")
        else:
            print(f"  SKIP {rename['old_name']}: {rename['new_name']} already exists")
    except Exception as e:
        print(f"  ERROR {rename['old_name']}: {e}")

print("\nDone!")
